"""Shared fixtures."""

from __future__ import annotations

import importlib.util
from pathlib import Path

import pytest

REPO_ROOT = Path(__file__).resolve().parents[1]


@pytest.fixture(scope="session")
def numbers_tex(tmp_path_factory: pytest.TempPathFactory) -> str:
    """``numbers.tex`` generated by ``scripts/make_numbers.py`` from ``results/``."""
    spec = importlib.util.spec_from_file_location(
        "make_numbers", REPO_ROOT / "scripts" / "make_numbers.py")
    mn = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mn)
    out = tmp_path_factory.mktemp("numbers") / "numbers.tex"
    assert mn.main(["--results-root", str(REPO_ROOT / "results"), "--out", str(out)]) == 0
    return out.read_text(encoding="utf-8")
